 ArrayList<Offer> callMcp(String origin,String destination,String date)throws Exception{URL u=new URL("https://flight-mcp.com/v1/flights/search/cached");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);String json="{\"origin\":\""+origin+"\",\"destination\":\""+destination+"\",\"departureDate\":\""+date+"\",\"maxResults\":20,\"cacheTtlSeconds\":604800}";c.getOutputStream().write(json.getBytes("UTF-8"));int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();BufferedReader br=new BufferedReader(new InputStreamReader(in));StringBuilder sb=new StringBuilder();String line;while((line=br.readLine())!=null)sb.append(line);br.close();if(code<200||code>=300)throw new Exception("Flight MCP HTTP "+code);JSONObject root=new JSONObject(sb.toString());JSONArray offers=root.optJSONArray("offers");ArrayList<Offer> list=new ArrayList<>();if(offers!=null)for(int i=0;i<offers.length();i++){JSONObject o=offers.optJSONObject(i);if(o==null)continue;JSONObject price=o.optJSONObject("price");String amount=price==null?"":String.valueOf(price.optInt("amountMinor",0)/100.0);String currency=price==null?"USD":price.optString("currency","USD");JSONArray its=o.optJSONArray("itineraries");if(its==null||its.length()==0)continue;JSONObject it=its.optJSONObject(0);JSONArray segs=it==null?null:it.optJSONArray("segments");if(segs==null||segs.length()==0)continue;JSONObject first=segs.optJSONObject(0),last=segs.optJSONObject(segs.length()-1);JSONObject carrier=first==null?null:first.optJSONObject("marketingCarrier");String airline=carrier==null?"Airline":carrier.optString("name","Airline");String carrierCode=carrier==null?"":carrier.optString("code","");String depAt=first==null?"":first.optString("departureAt","");String arrAt=last==null?"":last.optString("arrivalAt","");list.add(new Offer(airline,carrierCode,origin,destination,depAt,arrAt,it.optInt("durationMinutes",0),it.optInt("stops",0),amount,currency));}return list;}
